Page::IPCStableHashFunction Page::MessageToMethodInfo_(mojo::Message& message) {
#if !BUILDFLAG(IS_FUCHSIA)
  switch (static_cast<messages::Page>(message.name())) {
    case messages::Page::kOnAppInstalled: {
      return &Page::OnAppInstalled_Sym::IPCStableHash;
    }
    case messages::Page::kOnAppUpdated: {
      return &Page::OnAppUpdated_Sym::IPCStableHash;
    }
    case messages::Page::kOnAppUninstalled: {
      return &Page::OnAppUninstalled_Sym::IPCStableHash;
    }
  }
#endif  // !BUILDFLAG(IS_FUCHSIA)
  return nullptr;
}


const char* Page::MessageToMethodName_(mojo::Message& message) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  bool is_response = message.has_flag(mojo::Message::kFlagIsResponse);
  if (!is_response) {
    switch (static_cast<messages::Page>(message.name())) {
      case messages::Page::kOnAppInstalled:
            return "Receive iwa_dev::mojom::Page::OnAppInstalled";
      case messages::Page::kOnAppUpdated:
            return "Receive iwa_dev::mojom::Page::OnAppUpdated";
      case messages::Page::kOnAppUninstalled:
            return "Receive iwa_dev::mojom::Page::OnAppUninstalled";
    }
  } else {
    switch (static_cast<messages::Page>(message.name())) {
      case messages::Page::kOnAppInstalled:
            return "Receive reply iwa_dev::mojom::Page::OnAppInstalled";
      case messages::Page::kOnAppUpdated:
            return "Receive reply iwa_dev::mojom::Page::OnAppUpdated";
      case messages::Page::kOnAppUninstalled:
            return "Receive reply iwa_dev::mojom::Page::OnAppUninstalled";
    }
  }
  return "Receive unknown mojo message";
#else
  bool is_response = message.has_flag(mojo::Message::kFlagIsResponse);
  if (is_response) {
    return "Receive mojo reply";
  } else {
    return "Receive mojo message";
  }
#endif // BUILDFLAG(MOJO_TRACE_ENABLED)
}

