PageHandlerAsyncWaiter::PageHandlerAsyncWaiter(
    PageHandler* proxy) : proxy_(proxy) {}

PageHandlerAsyncWaiter::~PageHandlerAsyncWaiter() = default;


void PageHandlerAsyncWaiter::GetInstalledAppsInfo(
    std::vector<IwaDevModeAppInfoPtr>* out_apps) {
  base::RunLoop loop;
  proxy_->GetInstalledAppsInfo(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<IwaDevModeAppInfoPtr>* out_apps
,
             std::vector<IwaDevModeAppInfoPtr> apps) {*out_apps = std::move(apps);
            loop->Quit();
          },
          &loop,
          out_apps));
  loop.Run();
}

std::vector<IwaDevModeAppInfoPtr> PageHandlerAsyncWaiter::GetInstalledAppsInfo(
    ) {
  std::vector<IwaDevModeAppInfoPtr> async_wait_result;
  GetInstalledAppsInfo(&async_wait_result);
  return async_wait_result;
}

void PageHandlerAsyncWaiter::LaunchApp(
    const std::string& app_id, bool* out_success) {
  base::RunLoop loop;
  proxy_->LaunchApp(
      std::move(app_id),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_success
,
             bool success) {*out_success = std::move(success);
            loop->Quit();
          },
          &loop,
          out_success));
  loop.Run();
}

bool PageHandlerAsyncWaiter::LaunchApp(
    const std::string& app_id) {
  bool async_wait_result;
  LaunchApp(std::move(app_id),&async_wait_result);
  return async_wait_result;
}

void PageHandlerAsyncWaiter::UninstallApp(
    const std::string& app_id, bool* out_success) {
  base::RunLoop loop;
  proxy_->UninstallApp(
      std::move(app_id),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_success
,
             bool success) {*out_success = std::move(success);
            loop->Quit();
          },
          &loop,
          out_success));
  loop.Run();
}

bool PageHandlerAsyncWaiter::UninstallApp(
    const std::string& app_id) {
  bool async_wait_result;
  UninstallApp(std::move(app_id),&async_wait_result);
  return async_wait_result;
}




